export async function getServerSideProps({ res }) {
  const html = "<!DOCTYPE html>\n<html lang=\"vi\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>EQ & Self-Mastery \u00b7 PeopleOS by TaHien</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;0,800;1,700&family=Be+Vietnam+Pro:wght@300;400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n/* \u2500\u2500 TOKENS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n:root{\n  --navy:#020B18;--navy2:#062040;--navy3:#0A2E50;--navy4:#143350;\n  --cyan:#22D3EE;--teal:#06B6D4;--cyan2:#67E8F9;\n  --gold:#F0C040;--gold2:#FDE68A;--gold3:#d97706;\n  --text:#F0F6FF;--muted:#94A3B8;--subtle:#4A7A94;\n  --glass:rgba(255,255,255,0.04);--glass2:rgba(255,255,255,0.07);\n  --border:rgba(34,211,238,0.14);--border2:rgba(34,211,238,0.28);\n  --r:14px;--r-sm:9px;\n}\n/* \u2500\u2500 RESET \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n*{margin:0;padding:0;box-sizing:border-box}\nhtml{scroll-behavior:smooth;font-size:16px}\nbody{font-family:'Be Vietnam Pro',system-ui,sans-serif;background:var(--navy);\n  color:var(--text);min-height:100vh;overflow-x:hidden;line-height:1.6}\n/* \u2500\u2500 ATMOSPHERE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\nbody::before{content:'';position:fixed;inset:0;pointer-events:none;z-index:0;\n  background:\n    radial-gradient(ellipse 90% 55% at 15% -5%,rgba(6,182,212,.09) 0%,transparent 55%),\n    radial-gradient(ellipse 65% 45% at 85% 105%,rgba(240,192,64,.06) 0%,transparent 55%)}\nbody::after{content:'\u6c34';position:fixed;right:-50px;top:50%;\n  transform:translateY(-50%) rotate(-8deg);font-size:340px;line-height:1;\n  color:rgba(34,211,238,.022);pointer-events:none;z-index:0;\n  font-family:'Playfair Display',serif}\n/* \u2500\u2500 LAYOUT \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.app{position:relative;z-index:1;max-width:780px;margin:0 auto;padding:0 20px 100px}\n/* \u2500\u2500 TOPNAV \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.topnav{display:flex;align-items:center;justify-content:space-between;\n  padding:18px 0 14px;border-bottom:1px solid var(--border);margin-bottom:28px}\n.back{display:flex;align-items:center;gap:7px;font-size:13px;color:var(--muted);\n  text-decoration:none;transition:color .18s}\n.back:hover{color:var(--cyan)}\n.logo{display:flex;align-items:center;gap:9px}\n.lmark{width:30px;height:30px;border-radius:8px;\n  background:linear-gradient(135deg,var(--teal),var(--navy3));\n  display:flex;align-items:center;justify-content:center;\n  font-family:'Playfair Display',serif;font-size:13px;color:var(--cyan);\n  border:1px solid var(--border2)}\n.lname{font-size:13px;font-weight:600;color:var(--cyan);letter-spacing:.02em}\n.lsub{font-size:10px;color:var(--muted)}\n/* \u2500\u2500 PROGRESS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.prog-wrap{margin-bottom:24px}\n.prog-meta{display:flex;justify-content:space-between;\n  font-size:11px;color:var(--muted);margin-bottom:7px}\n.prog-bar{height:3px;background:rgba(255,255,255,.07);border-radius:2px;overflow:hidden}\n.prog-fill{height:100%;border-radius:2px;\n  background:linear-gradient(90deg,var(--teal),var(--cyan));\n  transition:width .55s cubic-bezier(.4,0,.2,1)}\n/* \u2500\u2500 MODULE DOTS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.dots{display:flex;gap:7px;justify-content:center;margin-bottom:28px}\n.dot{width:7px;height:7px;border-radius:50%;background:rgba(255,255,255,.1);\n  cursor:pointer;transition:all .22s;border:1.5px solid transparent;flex-shrink:0}\n.dot.active{background:var(--cyan);border-color:var(--cyan);transform:scale(1.4)}\n.dot.done{background:var(--teal);border-color:var(--teal)}\n/* \u2500\u2500 HERO \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.hero{position:relative;border-radius:var(--r);overflow:hidden;\n  margin-bottom:24px;height:190px;\n  border:1px solid var(--border)}\n.hero-bg{position:absolute;inset:0}\n.hero-grad{position:absolute;inset:0;\n  background:linear-gradient(135deg,var(--navy3) 0%,#0d2a46 50%,#041020 100%)}\n.hero-pattern{position:absolute;inset:0;opacity:.18;\n  background-image:repeating-linear-gradient(45deg,var(--cyan) 0,var(--cyan) 1px,transparent 0,transparent 50%);\n  background-size:24px 24px}\n.hero-overlay{position:absolute;inset:0;\n  background:linear-gradient(to top,rgba(2,11,24,.92) 0%,rgba(2,11,24,.3) 60%,transparent 100%)}\n.hero-content{position:absolute;bottom:18px;left:22px;right:22px}\n.hero-badge{display:inline-flex;align-items:center;gap:5px;\n  background:rgba(34,211,238,.13);border:1px solid var(--border2);\n  border-radius:20px;padding:3px 11px;font-size:11px;color:var(--cyan);\n  margin-bottom:9px;font-weight:500;letter-spacing:.05em}\n.hero-badge::before{content:'';width:5px;height:5px;border-radius:50%;background:var(--cyan)}\n.hero-num{font-size:12px;color:var(--muted);margin-bottom:4px}\n.hero-title{font-family:'Playfair Display',serif;font-size:22px;\n  font-weight:800;color:#fff;line-height:1.25}\n/* \u2500\u2500 MODULE VIEW \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.mv{display:none}\n.mv.active{display:block;animation:fadeUp .38s ease}\n@keyframes fadeUp{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}\n/* \u2500\u2500 CONTENT BLOCKS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.lead{border-left:2.5px solid var(--cyan);padding:13px 17px;\n  background:var(--glass);border-radius:0 var(--r-sm) var(--r-sm) 0;\n  font-style:italic;color:var(--text);font-size:14.5px;line-height:1.7;\n  margin-bottom:22px}\n.body{font-size:14.5px;line-height:1.78;color:var(--text);margin-bottom:15px}\n.body b{color:var(--cyan);font-weight:600}\n.sec-title{font-size:10.5px;letter-spacing:.13em;color:var(--teal);\n  font-weight:600;text-transform:uppercase;margin:22px 0 11px}\n/* \u2500\u2500 CARDS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-bottom:18px}\n@media(max-width:480px){.grid2{grid-template-columns:1fr}}\n.card{background:var(--glass);border:1px solid var(--border);\n  border-radius:var(--r-sm);padding:13px 15px}\n.cn{font-size:10px;color:var(--gold);font-weight:700;margin-bottom:5px;letter-spacing:.07em}\n.ct{font-size:13.5px;font-weight:600;color:var(--text);margin-bottom:4px}\n.cd{font-size:12.5px;color:var(--muted);line-height:1.5}\n/* \u2500\u2500 HIGHLIGHT / INSIGHT \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.hl{background:rgba(34,211,238,.06);border:1px solid rgba(34,211,238,.22);\n  border-radius:var(--r-sm);padding:14px 17px;margin-bottom:18px}\n.hl-label{font-size:10.5px;color:var(--cyan);font-weight:700;letter-spacing:.08em;margin-bottom:7px}\n.hl p{font-size:13.5px;color:var(--text);line-height:1.6}\n.ins{background:rgba(240,192,64,.06);border:1px solid rgba(240,192,64,.2);\n  border-radius:var(--r-sm);padding:13px 17px;margin-bottom:18px}\n.ins-label{font-size:10.5px;color:var(--gold);font-weight:700;letter-spacing:.08em;margin-bottom:6px}\n.ins p{font-size:13px;color:var(--text);line-height:1.55}\n/* \u2500\u2500 EXERCISE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.ex{background:var(--glass2);border:1px solid var(--border2);\n  border-radius:var(--r);padding:18px;margin-top:22px}\n.ex-head{display:flex;align-items:center;gap:10px;\n  margin-bottom:14px;padding-bottom:12px;border-bottom:1px solid var(--border)}\n.ex-ico{width:30px;height:30px;border-radius:8px;flex-shrink:0;\n  background:rgba(240,192,64,.13);border:1px solid rgba(240,192,64,.27);\n  display:flex;align-items:center;justify-content:center;font-size:14px}\n.ex-label{font-size:12.5px;font-weight:700;color:var(--gold)}\n.ex-sub{font-size:11px;color:var(--muted)}\n/* \u2500\u2500 QUIZ \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.qq{font-size:14px;color:var(--text);margin-bottom:13px;line-height:1.58;font-weight:500}\n.qopts{display:flex;flex-direction:column;gap:7px}\n.qopt{padding:11px 14px;border-radius:var(--r-sm);border:1px solid var(--border);\n  background:var(--glass);cursor:pointer;font-size:13.5px;color:var(--text);\n  transition:all .18s;text-align:left;width:100%;\n  display:flex;align-items:center;gap:9px;font-family:'Be Vietnam Pro',sans-serif}\n.qopt:hover:not(:disabled){border-color:var(--cyan);background:rgba(34,211,238,.07)}\n.qopt.correct{border-color:#22c55e!important;background:rgba(34,197,94,.09)!important;color:#86efac!important}\n.qopt.wrong{border-color:#ef4444!important;background:rgba(239,68,68,.09)!important;color:#fca5a5!important}\n.oletter{width:22px;height:22px;border-radius:50%;border:1px solid var(--border2);\n  display:flex;align-items:center;justify-content:center;\n  font-size:10.5px;color:var(--muted);flex-shrink:0;font-weight:700}\n.qfb{margin-top:11px;padding:11px 13px;border-radius:var(--r-sm);\n  font-size:13px;line-height:1.5;display:none}\n.qfb.show{display:block}\n.qfb.correct{background:rgba(34,197,94,.09);border:1px solid rgba(34,197,94,.27);color:#86efac}\n.qfb.wrong{background:rgba(239,68,68,.07);border:1px solid rgba(239,68,68,.2);color:#fca5a5}\n/* \u2500\u2500 EMOTION GRID \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.emgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}\n.embtn{padding:9px 6px;border-radius:var(--r-sm);border:1px solid var(--border);\n  background:var(--glass);cursor:pointer;text-align:center;\n  transition:all .18s;font-family:'Be Vietnam Pro',sans-serif}\n.embtn:hover:not(:disabled){border-color:var(--cyan);background:rgba(34,211,238,.08)}\n.embtn.sel{border-color:var(--cyan)!important;background:rgba(34,211,238,.1)!important}\n.emoj{font-size:21px;display:block;margin-bottom:3px}\n.emname{font-size:11.5px;color:var(--muted)}\n.embtn.sel .emname{color:var(--cyan)}\n/* \u2500\u2500 REFLECT \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.rlabel{font-size:13px;color:var(--muted);margin-bottom:7px;display:block}\n.rinput{width:100%;background:rgba(0,0,0,.25);border:1px solid var(--border);\n  border-radius:var(--r-sm);padding:11px 13px;color:var(--text);\n  font-family:'Be Vietnam Pro',sans-serif;font-size:13.5px;\n  resize:vertical;min-height:78px;transition:border .18s;line-height:1.6}\n.rinput:focus{outline:none;border-color:var(--cyan)}\n.rinput::placeholder{color:var(--subtle)}\n.chint{font-size:11px;color:var(--subtle);margin-top:5px;text-align:right;transition:color .2s}\n/* \u2500\u2500 SCALE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.slabels{display:flex;justify-content:space-between;margin-bottom:5px;font-size:11px;color:var(--muted)}\n.sslider{width:100%;-webkit-appearance:none;height:4px;\n  background:rgba(255,255,255,.1);border-radius:2px;outline:none}\n.sslider::-webkit-slider-thumb{-webkit-appearance:none;width:17px;height:17px;\n  border-radius:50%;background:var(--cyan);cursor:pointer;\n  border:2px solid var(--navy);box-shadow:0 0 0 3px rgba(34,211,238,.2)}\n.sval{text-align:center;margin-top:9px;font-size:17px;font-weight:700;color:var(--cyan)}\n/* \u2500\u2500 CHECKLIST \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.chi{display:flex;align-items:flex-start;gap:11px;padding:11px 0;\n  border-bottom:1px solid var(--border);cursor:pointer}\n.chi:last-child{border-bottom:none}\n.chbox{width:19px;height:19px;border-radius:5px;border:1.5px solid var(--border2);\n  flex-shrink:0;display:flex;align-items:center;justify-content:center;\n  transition:all .18s;margin-top:1px}\n.chbox.on{background:var(--cyan);border-color:var(--cyan)}\n.chbox.on::after{content:'\u2713';font-size:11px;color:var(--navy);font-weight:800}\n.chtext{font-size:13.5px;color:var(--text);line-height:1.5}\n.chtext small{display:block;font-size:11.5px;color:var(--muted);margin-top:2px}\n/* \u2500\u2500 TAKEAWAY \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.tw{background:linear-gradient(135deg,rgba(6,182,212,.09),rgba(240,192,64,.05));\n  border:1px solid var(--border2);border-radius:var(--r);\n  padding:18px 20px;margin-top:22px}\n.tw-label{font-size:10px;letter-spacing:.15em;color:var(--gold);\n  font-weight:700;text-transform:uppercase;margin-bottom:9px}\n.tw-text{font-family:'Playfair Display',serif;font-size:16px;\n  color:var(--text);line-height:1.65;font-style:italic}\n.tw-sig{font-size:11.5px;color:var(--muted);margin-top:9px}\n/* \u2500\u2500 NAV BUTTONS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.navbtns{display:flex;align-items:center;justify-content:space-between;\n  margin-top:28px;padding-top:18px;border-top:1px solid var(--border)}\n.btnprev{padding:10px 18px;border-radius:var(--r-sm);\n  border:1px solid var(--border);background:transparent;\n  color:var(--muted);font-family:'Be Vietnam Pro',sans-serif;\n  font-size:13.5px;cursor:pointer;transition:all .18s}\n.btnprev:hover:not(:disabled){border-color:var(--border2);color:var(--text)}\n.btnprev:disabled{opacity:.3;cursor:not-allowed}\n.btnnext{padding:11px 26px;border-radius:var(--r-sm);\n  background:linear-gradient(135deg,var(--teal),var(--cyan));\n  color:var(--navy);font-family:'Be Vietnam Pro',sans-serif;\n  font-size:13.5px;font-weight:700;cursor:pointer;border:none;\n  transition:all .2s;box-shadow:0 3px 14px rgba(34,211,238,.2)}\n.btnnext:hover:not(:disabled){transform:translateY(-1px);box-shadow:0 5px 18px rgba(34,211,238,.3)}\n.btnnext:disabled{opacity:.28;cursor:not-allowed;transform:none;\n  box-shadow:none;background:var(--subtle);color:var(--navy)}\n.ulock{font-size:11.5px;color:var(--subtle);text-align:center;margin-top:7px}\n/* \u2500\u2500 COMPLETE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.cscreen{text-align:center;padding:36px 16px;display:none}\n.cscreen.show{display:block;animation:fadeUp .45s ease}\n.cico{font-size:56px;margin-bottom:18px}\n.ctitle{font-family:'Playfair Display',serif;font-size:26px;\n  color:var(--text);margin-bottom:11px}\n.csub{font-size:14px;color:var(--muted);line-height:1.65;margin-bottom:24px}\n.certcard{background:var(--glass2);border:1px solid var(--border2);\n  border-radius:var(--r);padding:22px;margin-bottom:22px;\n  position:relative;overflow:hidden}\n.certcard::before{content:'PeopleOS';position:absolute;right:-20px;top:50%;\n  transform:translateY(-50%);font-family:'Playfair Display',serif;\n  font-size:72px;color:rgba(34,211,238,.04);pointer-events:none}\n.cert-lbl{font-size:11px;color:var(--cyan);letter-spacing:.12em;\n  font-weight:700;margin-bottom:7px}\n.cert-name{font-family:'Playfair Display',serif;font-size:20px;\n  color:var(--text);margin-bottom:5px}\n.cert-course{font-size:13px;color:var(--muted);margin-bottom:14px}\n.cert-sig{font-size:11.5px;color:var(--subtle);\n  border-top:1px solid var(--border);padding-top:11px;line-height:1.6}\n.btncert{width:100%;padding:13px;border-radius:var(--r-sm);\n  background:linear-gradient(135deg,var(--gold3),var(--gold));\n  color:var(--navy);font-family:'Be Vietnam Pro',sans-serif;\n  font-size:14px;font-weight:700;cursor:pointer;border:none;margin-bottom:9px}\n.btnnext2{width:100%;padding:11px;border-radius:var(--r-sm);\n  background:transparent;border:1px solid var(--border2);\n  color:var(--cyan);font-family:'Be Vietnam Pro',sans-serif;\n  font-size:13.5px;cursor:pointer;transition:background .18s}\n.btnnext2:hover{background:rgba(34,211,238,.07)}\n</style>\n</head>\n<body>\n<div class=\"app\">\n\n<!-- TOPNAV -->\n<nav class=\"topnav\">\n  <a class=\"back\" href=\"/\">\u2190 V\u1ec1 Learning Hub</a>\n  <div class=\"logo\">\n    <div class=\"lmark\">\u6c34</div>\n    <div>\n      <div class=\"lname\">PeopleOS</div>\n      <div class=\"lsub\">by TaHien</div>\n    </div>\n  </div>\n</nav>\n\n<!-- PROGRESS -->\n<div class=\"prog-wrap\">\n  <div class=\"prog-meta\">\n    <span id=\"plabel\">B\u00e0i 1 / 6</span>\n    <span id=\"ppct\">0%</span>\n  </div>\n  <div class=\"prog-bar\"><div class=\"prog-fill\" id=\"pfill\" style=\"width:0%\"></div></div>\n</div>\n\n<!-- DOTS -->\n<div class=\"dots\" id=\"dots\"></div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 M1 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div class=\"mv active\" id=\"m1\">\n  <div class=\"hero\">\n    <div class=\"hero-bg\">\n      <div class=\"hero-grad\"></div>\n      <div class=\"hero-pattern\"></div>\n    </div>\n    <div class=\"hero-overlay\"></div>\n    <div class=\"hero-content\">\n      <div class=\"hero-badge\">EQ & Self-Mastery \u00b7 C\u1ea5p 1</div>\n      <div class=\"hero-num\">B\u00e0i 1 / 6</div>\n      <div class=\"hero-title\">T\u1ea1i sao HR c\u1ea7n EQ h\u01a1n b\u1ea5t k\u1ef3 ng\u00e0nh n\u00e0o</div>\n    </div>\n  </div>\n\n  <div class=\"lead\">\"Hi\u1ec1n t\u1eebng g\u1eb7p m\u1ed9t HR Manager r\u1ea5t gi\u1ecfi quy tr\u00ecnh. H\u1ee3p \u0111\u1ed3ng kh\u00f4ng sai m\u1ed9t d\u1ea5u ph\u1ea9y. Policy vi\u1ebft chu\u1ea9n ch\u1ec9nh. Nh\u01b0ng m\u1ed7i l\u1ea7n nh\u00e2n vi\u00ean b\u01b0\u1edbc v\u00e0o ph\u00f2ng HR, h\u1ecd b\u01b0\u1edbc ra v\u1edbi c\u1ea3m gi\u00e1c b\u1ecb x\u00e9t x\u1eed \u2014 kh\u00f4ng ph\u1ea3i \u0111\u01b0\u1ee3c gi\u00fap \u0111\u1ee1. Ch\u00edn th\u00e1ng sau, c\u00f4 \u1ea5y chuy\u1ec3n b\u1ed9 ph\u1eadn. Kh\u00f4ng ph\u1ea3i v\u00ec thi\u1ebfu n\u0103ng l\u1ef1c. M\u00e0 v\u00ec thi\u1ebfu EQ.\"</div>\n\n  <p class=\"body\">H\u00e3y nh\u00ecn v\u00e0o m\u1ed9t ng\u00e0y l\u00e0m vi\u1ec7c b\u00ecnh th\u01b0\u1eddng c\u1ee7a HR: s\u00e1ng nghe nh\u00e2n vi\u00ean k\u1ec3 m\u00e2u thu\u1eabn v\u1edbi s\u1ebfp, tr\u01b0a d\u1ef1 calibration session m\u00e0 ai c\u0169ng b\u1ea3o v\u1ec7 ng\u01b0\u1eddi c\u1ee7a m\u00ecnh, chi\u1ec1u th\u00f4ng b\u00e1o m\u1ed9t ng\u01b0\u1eddi kh\u00f4ng qua th\u1eed vi\u1ec7c, t\u1ed1i nh\u1eadn email CEO h\u1ecfi t\u1ea1i sao turnover t\u0103ng. T\u1ea5t c\u1ea3 \u0111\u1ec1u \u0111\u00f2i h\u1ecfi m\u1ed9t th\u1ee9 tr\u01b0\u1edbc ti\u00ean: <b>kh\u1ea3 n\u0103ng \u0111\u1ecdc v\u00e0 qu\u1ea3n l\u00fd c\u1ea3m x\u00fac \u2014 c\u1ee7a ng\u01b0\u1eddi kh\u00e1c v\u00e0 c\u1ee7a ch\u00ednh m\u00ecnh.</b></p>\n\n  <div class=\"sec-title\">EQ kh\u00f4ng ph\u1ea3i \"hi\u1ec1n l\u00e0nh\" hay \"d\u1ec5 t\u00ednh\"</div>\n  <p class=\"body\">EQ cao l\u00e0 <b>bi\u1ebft khi n\u00e0o c\u1ea7n n\u00f3i th\u1eb3ng</b> v\u00e0 n\u00f3i th\u1eb3ng m\u00e0 ng\u01b0\u1eddi kia v\u1eabn c\u1ea3m th\u1ea5y \u0111\u01b0\u1ee3c t\u00f4n tr\u1ecdng. EQ cao l\u00e0 <b>ng\u1ed3i trong cu\u1ed9c sa th\u1ea3i m\u00e0 v\u1eabn gi\u1eef ph\u1ea9m gi\u00e1 cho c\u1ea3 hai ph\u00eda</b>. EQ cao l\u00e0 kh\u00f4ng b\u1ecb cu\u1ed1n v\u00e0o c\u1ea3m x\u00fac ph\u00f2ng h\u1ecdp \u2014 trong khi v\u1eabn \u0111\u1ecdc \u0111\u01b0\u1ee3c to\u00e0n b\u1ed9 c\u1ea3m x\u00fac \u0111\u00f3.</p>\n\n  <div class=\"sec-title\">5 th\u00e0nh ph\u1ea7n EQ theo Daniel Goleman</div>\n  <div class=\"grid2\">\n    <div class=\"card\"><div class=\"cn\">01</div><div class=\"ct\">T\u1ef1 nh\u1eadn th\u1ee9c</div><div class=\"cd\">Bi\u1ebft m\u00ecnh \u0111ang c\u1ea3m th\u1ea5y g\u00ec tr\u01b0\u1edbc khi n\u00f3 ki\u1ec3m so\u00e1t m\u00ecnh</div></div>\n    <div class=\"card\"><div class=\"cn\">02</div><div class=\"ct\">T\u1ef1 \u0111i\u1ec1u ch\u1ec9nh</div><div class=\"cd\">Ch\u1ecdn ph\u1ea3n \u1ee9ng thay v\u00ec b\u1ecb ph\u1ea3n \u1ee9ng \u0111i\u1ec1u khi\u1ec3n</div></div>\n    <div class=\"card\"><div class=\"cn\">03</div><div class=\"ct\">\u0110\u1ed9ng l\u1ef1c n\u1ed9i t\u1ea1i</div><div class=\"cd\">L\u00e0m v\u00ec \u00fd ngh\u0129a \u2014 kh\u00f4ng ch\u1ec9 v\u00ec ch\u1ee9c danh hay l\u01b0\u01a1ng</div></div>\n    <div class=\"card\"><div class=\"cn\">04</div><div class=\"ct\">\u0110\u1ed3ng c\u1ea3m</div><div class=\"cd\">Hi\u1ec3u c\u1ea3m x\u00fac ng\u01b0\u1eddi kh\u00e1c m\u00e0 kh\u00f4ng h\u00f2a tan v\u00e0o \u0111\u00f3</div></div>\n  </div>\n  <div class=\"hl\">\n    <div class=\"hl-label\">+ Th\u00e0nh ph\u1ea7n th\u1ee9 6 \u00b7 TaHien b\u1ed5 sung</div>\n    <p><b style=\"color:var(--cyan)\">Duy tr\u00ec ranh gi\u1edbi c\u1ea3m x\u00fac trong khi v\u1eabn k\u1ebft n\u1ed1i th\u1eadt s\u1ef1.</b> \u0110\u00e2y l\u00e0 th\u1ee9 kh\u00f4ng tr\u01b0\u1eddng n\u00e0o d\u1ea1y \u2014 nh\u01b0ng ph\u00e2n bi\u1ec7t HR xu\u1ea5t s\u1eafc v\u1edbi HR gi\u1ecfi nghi\u1ec7p v\u1ee5.</p>\n  </div>\n\n  <!-- EXERCISE -->\n  <div class=\"ex\">\n    <div class=\"ex-head\">\n      <div class=\"ex-ico\">\ud83c\udfaf</div>\n      <div><div class=\"ex-label\">Ki\u1ec3m tra nhanh</div><div class=\"ex-sub\">Ch\u1ecdn \u0111\u00e1p \u00e1n ph\u1ea3n \u00e1nh EQ cao nh\u1ea5t</div></div>\n    </div>\n    <div class=\"qq\">M\u1ed9t manager ph\u1ea3n \u1ee9ng gay g\u1eaft khi HR th\u00f4ng b\u00e1o ch\u00ednh s\u00e1ch m\u1edbi. Ph\u1ea3n \u1ee9ng n\u00e0o th\u1ec3 hi\u1ec7n EQ cao nh\u1ea5t?</div>\n    <div class=\"qopts\" id=\"q1opts\">\n      <button class=\"qopt\" onclick=\"A1(this,'A')\"><span class=\"oletter\">A</span>Gi\u1ea3i th\u00edch ngay l\u00fd do t\u1ea1i sao ch\u00ednh s\u00e1ch \u0111\u00f3 \u0111\u00fang</button>\n      <button class=\"qopt\" onclick=\"A1(this,'B')\"><span class=\"oletter\">B</span>H\u1ecfi: \"\u0110i\u1ec1u g\u00ec khi\u1ebfn anh lo ng\u1ea1i nh\u1ea5t v\u1ec1 ch\u00ednh s\u00e1ch n\u00e0y?\"</button>\n      <button class=\"qopt\" onclick=\"A1(this,'C')\"><span class=\"oletter\">C</span>\u0110\u1ed3ng \u00fd v\u1edbi manager \u0111\u1ec3 tr\u00e1nh leo thang xung \u0111\u1ed9t</button>\n      <button class=\"qopt\" onclick=\"A1(this,'D')\"><span class=\"oletter\">D</span>B\u00e1o c\u00e1o l\u00ean c\u1ea5p tr\u00ean \u0111\u1ec3 x\u1eed l\u00fd</button>\n    </div>\n    <div class=\"qfb\" id=\"qf1\"></div>\n  </div>\n\n  <div class=\"tw\">\n    <div class=\"tw-label\">C\u00e2u mang \u0111i \u00b7 B\u00e0i 1</div>\n    <div class=\"tw-text\">\"EQ kh\u00f4ng ph\u1ea3i t\u00ednh c\u00e1ch b\u1ea9m sinh. \u0110\u00f3 l\u00e0 h\u1ec7 c\u01a1 \u2014 c\u00f3 th\u1ec3 luy\u1ec7n t\u1eadp m\u1ed7i ng\u00e0y. V\u00e0 v\u1edbi ng\u01b0\u1eddi l\u00e0m HR, \u0111\u00e2y l\u00e0 h\u1ec7 c\u01a1 quan tr\u1ecdng nh\u1ea5t.\"</div>\n    <div class=\"tw-sig\">\u2014 TaHien \u00b7 CHCO Golden Gate Group</div>\n  </div>\n  <div class=\"navbtns\">\n    <button class=\"btnprev\" disabled>\u2190 Quay l\u1ea1i</button>\n    <button class=\"btnnext\" id=\"n1\" onclick=\"go(2)\" disabled>Ti\u1ebfp theo \u2192</button>\n  </div>\n  <div class=\"ulock\" id=\"h1\">Tr\u1ea3 l\u1eddi c\u00e2u h\u1ecfi \u0111\u1ec3 m\u1edf b\u00e0i ti\u1ebfp theo</div>\n</div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 M2 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div class=\"mv\" id=\"m2\">\n  <div class=\"hero\">\n    <div class=\"hero-bg\"><div class=\"hero-grad\"></div><div class=\"hero-pattern\"></div></div>\n    <div class=\"hero-overlay\"></div>\n    <div class=\"hero-content\">\n      <div class=\"hero-badge\">EQ & Self-Mastery \u00b7 C\u1ea5p 1</div>\n      <div class=\"hero-num\">B\u00e0i 2 / 6</div>\n      <div class=\"hero-title\">Nh\u1eadn di\u1ec7n 6 c\u1ea3m x\u00fac c\u1ed1t l\u00f5i trong workplace</div>\n    </div>\n  </div>\n\n  <div class=\"lead\">\"Em kh\u00f4ng hi\u1ec3u t\u1ea1i sao anh \u1ea5y ph\u1ea3n \u1ee9ng d\u1eef v\u1eady \u2014 em ch\u1ec9 th\u00f4ng b\u00e1o thay \u0111\u1ed5i ch\u00ednh s\u00e1ch th\u00f4i.\" Hi\u1ec1n h\u1ecfi: \"L\u00fac em th\u00f4ng b\u00e1o, anh \u1ea5y \u0111ang nh\u00ecn \u0111\u00e2u? Tay anh \u1ea5y l\u00e0m g\u00ec?\" C\u00f4 HR tr\u1ebb kh\u00f4ng nh\u1edb. V\u00ec c\u00f4 kh\u00f4ng \u0111\u01b0\u1ee3c d\u1ea1y c\u00e1ch quan s\u00e1t.\"</div>\n\n  <p class=\"body\">Paul Ekman x\u00e1c \u0111\u1ecbnh 6 c\u1ea3m x\u00fac ph\u1ed5 qu\u00e1t c\u1ee7a con ng\u01b0\u1eddi. Nh\u01b0ng trong workplace, ch\u00fang kh\u00f4ng xu\u1ea5t hi\u1ec7n d\u01b0\u1edbi d\u1ea1ng thu\u1ea7n khi\u1ebft \u2014 ch\u00fang b\u1ecb <b>che ph\u1ee7, m\u00e3 h\u00f3a, v\u00e0 ng\u1ee5y trang</b> th\u00e0nh th\u1ee9 ho\u00e0n to\u00e0n kh\u00e1c.</p>\n\n  <div class=\"sec-title\">6 c\u1ea3m x\u00fac & c\u00e1ch nh\u1eadn di\u1ec7n trong m\u00f4i tr\u01b0\u1eddng HR</div>\n  <div class=\"grid2\">\n    <div class=\"card\"><div class=\"cn\" style=\"color:#ef4444\">T\u1ee9c gi\u1eadn</div><div class=\"ct\">Hi\u1ebfm khi l\u00e0 la h\u00e9t</div><div class=\"cd\">Im l\u1eb7ng \u0111\u1ed9t ng\u1ed9t, gi\u1ecdng b\u1eb1ng ph\u1eb3ng, \"\u0111\u1ed3ng \u00fd t\u1ea5t c\u1ea3\" sau khi tranh lu\u1eadn gay g\u1eaft</div></div>\n    <div class=\"card\"><div class=\"cn\" style=\"color:#a78bfa\">S\u1ee3 h\u00e3i</div><div class=\"ct\">Ph\u1ed5 bi\u1ebfn nh\u1ea5t \u2014 b\u1ecb che gi\u1ea5u nhi\u1ec1u nh\u1ea5t</div><div class=\"cd\">N\u00f3i nhi\u1ec1u nh\u01b0ng kh\u00f4ng n\u00f3i th\u1eadt. \u0110\u1ed3ng \u00fd mi\u1ec7ng nh\u01b0ng kh\u00f4ng h\u00e0nh \u0111\u1ed9ng</div></div>\n    <div class=\"card\"><div class=\"cn\" style=\"color:#60a5fa\">Bu\u1ed3n</div><div class=\"ct\">R\u00fat lui, kh\u00f4ng n\u1ed5i gi\u1eadn</div><div class=\"cd\">Hi\u1ec7u su\u1ea5t gi\u1ea3m d\u1ea7n, \u00edt tham gia h\u1ecdp, c\u00e2u tr\u1ea3 l\u1eddi ng\u1eafn v\u00e0 th\u1ee5 \u0111\u1ed9ng</div></div>\n    <div class=\"card\"><div class=\"cn\" style=\"color:#f97316\">Gh\u00ea t\u1edfm</div><div class=\"ct\">Kh\u00f3 x\u1eed l\u00fd nh\u1ea5t</div><div class=\"cd\">\"T\u00f4i hi\u1ec3u t\u1ea1i sao c\u00f4ng ty l\u00e0m v\u1eady\" v\u1edbi gi\u1ecdng ph\u1eb3ng = \u0111\u00e3 quy\u1ebft \u0111\u1ecbnh r\u1eddi \u0111i</div></div>\n    <div class=\"card\"><div class=\"cn\" style=\"color:#22c55e\">Vui</div><div class=\"ct\">C\u01a1 h\u1ed9i b\u1ecb b\u1ecf l\u1ee1 nhi\u1ec1u nh\u1ea5t</div><div class=\"cd\">Khi \u00e1nh m\u1eaft nh\u00e2n vi\u00ean s\u00e1ng l\u00ean \u2014 HR c\u00f3 30 gi\u00e2y v\u00e0ng \u0111\u1ec3 nh\u00e2n l\u00ean \u0111\u1ed9ng l\u1ef1c \u0111\u00f3</div></div>\n    <div class=\"card\"><div class=\"cn\" style=\"color:var(--cyan)\">Ng\u1ea1c nhi\u00ean</div><div class=\"ct\">C\u00e1nh c\u1eeda d\u1eabn \u0111\u1ebfn 5 c\u1ea3m x\u00fac c\u00f2n l\u1ea1i</div><div class=\"cd\">10 gi\u00e2y ph\u1ea3n \u1ee9ng \u0111\u1ea7u ti\u00ean c\u1ee7a HR quy\u1ebft \u0111\u1ecbnh ng\u01b0\u1eddi kia \u0111i v\u1ec1 h\u01b0\u1edbng n\u00e0o</div></div>\n  </div>\n\n  <div class=\"ex\">\n    <div class=\"ex-head\">\n      <div class=\"ex-ico\">\ud83d\udd0d</div>\n      <div><div class=\"ex-label\">Nh\u1eadn di\u1ec7n t\u00ecnh hu\u1ed1ng</div><div class=\"ex-sub\">\u0110\u1ecdc t\u00ecnh hu\u1ed1ng \u2014 ch\u1ecdn c\u1ea3m x\u00fac ch\u00ednh</div></div>\n    </div>\n    <p style=\"font-size:13.5px;color:var(--text);margin-bottom:13px;line-height:1.6\"><b>T\u00ecnh hu\u1ed1ng:</b> Trong bu\u1ed5i h\u1ecdp th\u00f4ng b\u00e1o c\u01a1 c\u1ea5u l\u1ea1i, m\u1ed9t nh\u00e2n vi\u00ean l\u00e2u n\u0103m ng\u1ed3i im su\u1ed1t, kh\u00f4ng h\u1ecfi g\u00ec, cu\u1ed1i bu\u1ed5i ch\u1ec9 n\u00f3i \"C\u1ea3m \u01a1n\" r\u1ed3i ra v\u1ec1. H\u00f4m sau hi\u1ec7u su\u1ea5t gi\u1ea3m h\u1eb3n.</p>\n    <p style=\"font-size:12.5px;color:var(--muted);margin-bottom:11px\">C\u1ea3m x\u00fac ch\u00ednh anh \u1ea5y \u0111ang tr\u1ea3i qua l\u00e0 g\u00ec?</p>\n    <div class=\"emgrid\" id=\"emg\">\n      <button class=\"embtn\" onclick=\"PE(this,'wrong')\"><span class=\"emoj\">\ud83d\ude21</span><span class=\"emname\">T\u1ee9c gi\u1eadn</span></button>\n      <button class=\"embtn\" onclick=\"PE(this,'ok')\"><span class=\"emoj\">\ud83d\ude14</span><span class=\"emname\">Bu\u1ed3n / v\u00f4 h\u00ecnh</span></button>\n      <button class=\"embtn\" onclick=\"PE(this,'wrong')\"><span class=\"emoj\">\ud83d\ude28</span><span class=\"emname\">S\u1ee3 h\u00e3i</span></button>\n      <button class=\"embtn\" onclick=\"PE(this,'wrong')\"><span class=\"emoj\">\ud83d\ude32</span><span class=\"emname\">Ng\u1ea1c nhi\u00ean</span></button>\n      <button class=\"embtn\" onclick=\"PE(this,'wrong')\"><span class=\"emoj\">\ud83d\ude0a</span><span class=\"emname\">Vui</span></button>\n      <button class=\"embtn\" onclick=\"PE(this,'wrong')\"><span class=\"emoj\">\ud83e\udd22</span><span class=\"emname\">Gh\u00ea t\u1edfm</span></button>\n    </div>\n    <div class=\"qfb\" id=\"ef2\"></div>\n  </div>\n\n  <div class=\"tw\">\n    <div class=\"tw-label\">C\u00e2u mang \u0111i \u00b7 B\u00e0i 2</div>\n    <div class=\"tw-text\">\"C\u1ea3m x\u00fac kh\u00f4ng bao gi\u1edd n\u00f3i th\u1eb3ng \u2014 ch\u00fang n\u00f3i qua c\u01a1 th\u1ec3, gi\u1ecdng, v\u00e0 kho\u1ea3ng l\u1eb7ng. Ng\u01b0\u1eddi HR gi\u1ecfi h\u1ecdc c\u00e1ch \u0111\u1ecdc ba k\u00eanh \u0111\u00f3 song song.\"</div>\n    <div class=\"tw-sig\">\u2014 TaHien \u00b7 CHCO Golden Gate Group</div>\n  </div>\n  <div class=\"navbtns\">\n    <button class=\"btnprev\" onclick=\"go(1)\">\u2190 Quay l\u1ea1i</button>\n    <button class=\"btnnext\" id=\"n2\" onclick=\"go(3)\" disabled>Ti\u1ebfp theo \u2192</button>\n  </div>\n  <div class=\"ulock\" id=\"h2\">Ch\u1ecdn c\u1ea3m x\u00fac \u0111\u1ec3 ti\u1ebfp t\u1ee5c</div>\n</div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 M3 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div class=\"mv\" id=\"m3\">\n  <div class=\"hero\">\n    <div class=\"hero-bg\"><div class=\"hero-grad\"></div><div class=\"hero-pattern\"></div></div>\n    <div class=\"hero-overlay\"></div>\n    <div class=\"hero-content\">\n      <div class=\"hero-badge\">EQ & Self-Mastery \u00b7 C\u1ea5p 1</div>\n      <div class=\"hero-num\">B\u00e0i 3 / 6</div>\n      <div class=\"hero-title\">\u0110\u1ecdc v\u1ecb ng\u01b0\u1eddi \u2014 ng\u00f4n ng\u1eef c\u01a1 th\u1ec3 th\u1ef1c chi\u1ebfn</div>\n    </div>\n  </div>\n\n  <div class=\"lead\">\"Khi ph\u1ecfng v\u1ea5n, b\u1ea1n tin v\u00e0o nh\u1eefng g\u00ec \u1ee9ng vi\u00ean n\u00f3i, hay nh\u1eefng g\u00ec c\u01a1 th\u1ec3 h\u1ecd n\u00f3i?\" \u2014 H\u1ea7u h\u1ebft HR tr\u1ea3 l\u1eddi: \"C\u1ea3 hai.\" Nh\u01b0ng khi \u0111\u01b0\u1ee3c h\u1ecfi \"L\u1ea7n cu\u1ed1i l\u1eddi n\u00f3i v\u00e0 c\u01a1 th\u1ec3 m\u00e2u thu\u1eabn nhau, b\u1ea1n tin c\u00e1i n\u00e0o?\" \u2014 c\u00e2u tr\u1ea3 l\u1eddi th\u01b0\u1eddng l\u00e0 im l\u1eb7ng.\"</div>\n\n  <div class=\"ins\">\n    <div class=\"ins-label\">Nguy\u00ean l\u00fd 7-38-55 \u00b7 Albert Mehrabian</div>\n    <p>Trong giao ti\u1ebfp c\u1ea3m x\u00fac: <b style=\"color:var(--gold)\">7%</b> t\u1eeb l\u1eddi n\u00f3i \u00b7 <b style=\"color:var(--gold)\">38%</b> t\u1eeb gi\u1ecdng \u0111i\u1ec7u \u00b7 <b style=\"color:var(--gold)\">55%</b> t\u1eeb ng\u00f4n ng\u1eef c\u01a1 th\u1ec3. Khi ng\u01b0\u1eddi ta che gi\u1ea5u \u2014 c\u01a1 th\u1ec3 ph\u1ea3n b\u1ed9i tr\u01b0\u1edbc khi mi\u1ec7ng k\u1ecbp \u0111i\u1ec1u ch\u1ec9nh.</p>\n  </div>\n\n  <div class=\"sec-title\">5 t\u00edn hi\u1ec7u HR c\u1ea7n \u0111\u1ecdc ngay</div>\n  <div class=\"grid2\">\n    <div class=\"card\"><div class=\"cn\">01</div><div class=\"ct\">Kh\u00f4ng nh\u1ea5t qu\u00e1n</div><div class=\"cd\">N\u00f3i \"T\u00f4i \u1ed5n\" nh\u01b0ng tay si\u1ebft ch\u1eb7t, gi\u1ecdng run \u2192 c\u00f2n th\u1ee9 g\u00ec ch\u01b0a \u0111\u01b0\u1ee3c n\u00f3i ra</div></div>\n    <div class=\"card\"><div class=\"cn\">02</div><div class=\"ct\">T\u1ef1 ch\u1ea1m (self-touching)</div><div class=\"cd\">Ch\u1ea1m m\u1eb7t, c\u1ed5, t\u00f3c khi kh\u00f4ng ch\u1eafc \u2192 c\u00e2u h\u1ecfi \u0111\u00f3 c\u1ea7n \u0111\u00e0o s\u00e2u h\u01a1n</div></div>\n    <div class=\"card\"><div class=\"cn\">03</div><div class=\"ct\">H\u01b0\u1edbng c\u01a1 th\u1ec3</div><div class=\"cd\">Quay c\u01a1 th\u1ec3 ra c\u1eeda (kh\u00f4ng ch\u1ec9 nh\u00ecn) \u2192 mu\u1ed1n tho\u00e1t kh\u1ecfi t\u00ecnh hu\u1ed1ng</div></div>\n    <div class=\"card\"><div class=\"cn\">04</div><div class=\"ct\">Micro-expressions</div><div class=\"cd\">Bi\u1ec3u c\u1ea3m &lt;0.25 gi\u00e2y \u2014 x\u1ea3y ra tr\u01b0\u1edbc khi n\u00e3o ki\u1ec3m so\u00e1t. Ph\u1ea3i nh\u00ecn th\u1eb3ng v\u00e0o m\u1eb7t ng\u01b0\u1eddi kia</div></div>\n  </div>\n  <div class=\"hl\">\n    <div class=\"hl-label\">Nguy\u00ean t\u1eafc v\u00e0ng khi \u0111\u1ecdc c\u01a1 th\u1ec3</div>\n    <p>Kh\u00f4ng ph\u1ea3i \u0111\u1ec3 \"b\u1eaft qu\u1ea3 tang\" \u2014 m\u00e0 \u0111\u1ec3 bi\u1ebft khi n\u00e0o c\u1ea7n t\u1ea1o kh\u00f4ng gian an to\u00e0n h\u01a1n. Khi th\u1ea5y t\u00edn hi\u1ec7u m\u00e2u thu\u1eabn, h\u1ecfi: <b style=\"color:var(--cyan)\">\"T\u00f4i c\u00f3 c\u1ea3m gi\u00e1c c\u00f2n \u0111i\u1ec1u g\u00ec \u0111\u00f3 ch\u01b0a n\u00f3i h\u1ebft \u2014 anh c\u00f3 mu\u1ed1n chia s\u1ebb th\u00eam kh\u00f4ng?\"</b></p>\n  </div>\n\n  <div class=\"ex\">\n    <div class=\"ex-head\">\n      <div class=\"ex-ico\">\ud83d\udc41\ufe0f</div>\n      <div><div class=\"ex-label\">\u0110\u1ecdc t\u00ecnh hu\u1ed1ng</div><div class=\"ex-sub\">X\u00e1c \u0111\u1ecbnh ph\u1ea3n \u1ee9ng HR \u0111\u00fang nh\u1ea5t</div></div>\n    </div>\n    <div class=\"qq\">Trong exit interview, khi h\u1ecfi l\u00fd do ngh\u1ec9, nh\u00e2n vi\u00ean th\u1edf nhanh h\u01a1n v\u00e0 nh\u1ecbp n\u00f3i ch\u1eadm l\u1ea1i khi nh\u1eafc \u0111\u1ebfn t\u00ean m\u1ed9t ng\u01b0\u1eddi c\u1ee5 th\u1ec3. HR n\u00ean l\u00e0m g\u00ec?</div>\n    <div class=\"qopts\" id=\"q3opts\">\n      <button class=\"qopt\" onclick=\"A3(this,'A')\"><span class=\"oletter\">A</span>H\u1ecfi th\u1eb3ng: \"Anh c\u00f3 v\u1ea5n \u0111\u1ec1 v\u1edbi ng\u01b0\u1eddi \u0111\u00f3 kh\u00f4ng?\"</button>\n      <button class=\"qopt\" onclick=\"A3(this,'B')\"><span class=\"oletter\">B</span>B\u1ecf qua \u2014 ch\u1ec9 l\u00e0 ph\u1ea3n \u1ee9ng b\u00ecnh th\u01b0\u1eddng</button>\n      <button class=\"qopt\" onclick=\"A3(this,'C')\"><span class=\"oletter\">C</span>T\u1ea1m d\u1eebng, h\u1ecfi m\u1edf: \"Anh c\u00f3 th\u1ec3 k\u1ec3 th\u00eam v\u1ec1 m\u1ed1i quan h\u1ec7 \u0111\u00f3 kh\u00f4ng?\"</button>\n      <button class=\"qopt\" onclick=\"A3(this,'D')\"><span class=\"oletter\">D</span>K\u1ebft th\u00fac bu\u1ed5i s\u1edbm v\u00ec nh\u00e2n vi\u00ean kh\u00f4ng tho\u1ea3i m\u00e1i</button>\n    </div>\n    <div class=\"qfb\" id=\"qf3\"></div>\n  </div>\n\n  <div class=\"tw\">\n    <div class=\"tw-label\">C\u00e2u mang \u0111i \u00b7 B\u00e0i 3</div>\n    <div class=\"tw-text\">\"Trong m\u1ecdi cu\u1ed9c tr\u00f2 chuy\u1ec7n HR, h\u00e3y l\u1eafng nghe b\u1eb1ng tai \u2014 nh\u01b0ng quan s\u00e1t b\u1eb1ng m\u1eaft. Hai th\u1ee9 \u0111\u00f3 th\u01b0\u1eddng k\u1ec3 hai c\u00e2u chuy\u1ec7n kh\u00e1c nhau.\"</div>\n    <div class=\"tw-sig\">\u2014 TaHien \u00b7 CHCO Golden Gate Group</div>\n  </div>\n  <div class=\"navbtns\">\n    <button class=\"btnprev\" onclick=\"go(2)\">\u2190 Quay l\u1ea1i</button>\n    <button class=\"btnnext\" id=\"n3\" onclick=\"go(4)\" disabled>Ti\u1ebfp theo \u2192</button>\n  </div>\n  <div class=\"ulock\" id=\"h3\">Tr\u1ea3 l\u1eddi c\u00e2u h\u1ecfi \u0111\u1ec3 ti\u1ebfp t\u1ee5c</div>\n</div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 M4 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div class=\"mv\" id=\"m4\">\n  <div class=\"hero\">\n    <div class=\"hero-bg\"><div class=\"hero-grad\"></div><div class=\"hero-pattern\"></div></div>\n    <div class=\"hero-overlay\"></div>\n    <div class=\"hero-content\">\n      <div class=\"hero-badge\">EQ & Self-Mastery \u00b7 C\u1ea5p 1</div>\n      <div class=\"hero-num\">B\u00e0i 4 / 6</div>\n      <div class=\"hero-title\">Ki\u1ec3m so\u00e1t c\u1ea3m x\u00fac d\u01b0\u1edbi \u00e1p l\u1ef1c</div>\n    </div>\n  </div>\n\n  <div class=\"lead\">\"C\u00f3 kho\u1ea3nh kh\u1eafc m\u00e0 h\u1ea7u h\u1ebft HR \u0111\u1ec1u tr\u1ea3i qua \u00edt nh\u1ea5t m\u1ed9t l\u1ea7n: ng\u1ed3i v\u1edbi nh\u00e2n vi\u00ean \u0111ang kh\u00f3c ho\u1eb7c \u0111ang n\u1ed5i gi\u1eadn \u2014 v\u00e0 kh\u00f4ng bi\u1ebft ph\u1ea3i l\u00e0m g\u00ec v\u1edbi c\u1ea3m x\u00fac c\u1ee7a ch\u00ednh m\u00ecnh. Kh\u00f4ng ph\u1ea3i v\u00ec kh\u00f4ng c\u00f3 k\u1ef9 n\u0103ng. M\u00e0 v\u00ec c\u1ea3m x\u00fac c\u1ee7a ng\u01b0\u1eddi kia \u0111\u00e3 lan sang h\u1ecd tr\u01b0\u1edbc khi h\u1ecd k\u1ecbp nh\u1eadn ra.\"</div>\n\n  <div class=\"ins\">\n    <div class=\"ins-label\">Emotional contagion \u00b7 Khoa h\u1ecdc th\u1ea7n kinh</div>\n    <p>N\u00e3o ng\u01b0\u1eddi kh\u00f4ng ph\u00e2n bi\u1ec7t \"\u0111\u00e2y l\u00e0 c\u1ea3m x\u00fac c\u1ee7a t\u00f4i\" v\u00e0 \"\u0111\u00e2y l\u00e0 c\u1ea3m x\u00fac t\u00f4i h\u1ea5p thu t\u1eeb ng\u01b0\u1eddi kh\u00e1c.\" Khi ng\u1ed3i v\u1edbi ng\u01b0\u1eddi \u0111ang s\u1ee3, amygdala c\u1ee7a b\u1ea1n ph\u1ea3n \u1ee9ng nh\u01b0 th\u1ec3 b\u1ea1n c\u0169ng \u0111ang trong nguy hi\u1ec3m. \u0110\u00e2y l\u00e0 l\u00fd do sau m\u1ed9t ng\u00e0y d\u00e0y \u0111\u1eb7c cu\u1ed9c tr\u00f2 chuy\u1ec7n c\u1ea3m x\u00fac, nhi\u1ec1u HR v\u1ec1 nh\u00e0 ki\u1ec7t s\u1ee9c m\u00e0 kh\u00f4ng hi\u1ec3u t\u1ea1i sao.</p>\n  </div>\n\n  <div class=\"sec-title\">3 k\u1ef9 thu\u1eadt reframing th\u1ef1c chi\u1ebfn</div>\n  <div class=\"card\" style=\"margin-bottom:9px\">\n    <div class=\"cn\">K\u1ef9 thu\u1eadt 1 \u00b7 Observer mode</div>\n    <div class=\"ct\">Quan s\u00e1t thay v\u00ec h\u00f2a tan</div>\n    <div class=\"cd\">\u0110\u1eb7t t\u00ean cho c\u1ea3m x\u00fac \u0111ang c\u1ea3m th\u1ea5y: \"T\u00f4i \u0111ang mu\u1ed1n t\u1ef1 b\u00e0o ch\u1eefa.\" Nghi\u00ean c\u1ee9u cho th\u1ea5y ch\u1ec9 \u0111\u1eb7t t\u00ean l\u00e0 \u0111\u00e3 gi\u1ea3m 30\u201340% c\u01b0\u1eddng \u0111\u1ed9 c\u1ea3m x\u00fac \u0111\u00f3 \u2014 v\u00ec k\u00edch ho\u1ea1t prefrontal cortex, gi\u1ea3m amygdala.</div>\n  </div>\n  <div class=\"card\" style=\"margin-bottom:9px\">\n    <div class=\"cn\">K\u1ef9 thu\u1eadt 2 \u00b7 Reframe tr\u01b0\u1edbc khi ph\u1ea3n \u1ee9ng</div>\n    <div class=\"ct\">Thay \"ph\u00f2ng th\u1ee7\" b\u1eb1ng \"t\u00f2 m\u00f2\"</div>\n    <div class=\"cd\">Khi manager n\u1ed5i gi\u1eadn: reframe trong \u0111\u1ea7u \u2014 \"Ng\u01b0\u1eddi n\u00e0y kh\u00f4ng t\u1ee9c gi\u1eadn v\u1edbi t\u00f4i \u2014 h\u1ecd \u0111ang s\u1ee3 m\u1ea5t quy\u1ec1n ki\u1ec3m so\u00e1t.\" C\u00e2u reframe kh\u00f4ng c\u1ea7n n\u00f3i ra. N\u00f3 ch\u1ec9 c\u1ea7n x\u1ea3y ra trong \u0111\u1ea7u b\u1ea1n.</div>\n  </div>\n  <div class=\"card\" style=\"margin-bottom:18px\">\n    <div class=\"cn\">K\u1ef9 thu\u1eadt 3 \u00b7 Pause c\u00f3 ch\u1ee7 \u0111\u00edch</div>\n    <div class=\"ct\">M\u1edf r\u1ed9ng \"kho\u1ea3ng tr\u1ed1ng\" gi\u1eefa k\u00edch th\u00edch v\u00e0 ph\u1ea3n \u1ee9ng</div>\n    <div class=\"cd\">Viktor Frankl: \"Between stimulus and response there is a space.\" \u0110\u01a1n gi\u1ea3n nh\u1ea5t: l\u1eb7p l\u1ea1i c\u00e2u cu\u1ed1i c\u1ee7a ng\u01b0\u1eddi kia d\u01b0\u1edbi d\u1ea1ng c\u00e2u h\u1ecfi \u2014 mua th\u00eam 10 gi\u00e2y, \u0111\u1ed3ng th\u1eddi l\u00e0m ng\u01b0\u1eddi kia c\u1ea3m th\u1ea5y \u0111\u01b0\u1ee3c nghe.</div>\n  </div>\n\n  <div class=\"ex\">\n    <div class=\"ex-head\">\n      <div class=\"ex-ico\">\ud83e\ude9e</div>\n      <div><div class=\"ex-label\">T\u1ef1 \u0111\u00e1nh gi\u00e1</div><div class=\"ex-sub\">Th\u00e0nh th\u1eadt v\u1edbi b\u1ea3n th\u00e2n</div></div>\n    </div>\n    <p style=\"font-size:13px;color:var(--muted);margin-bottom:14px\">Khi b\u1ecb ph\u1ea3n \u1ee9ng gay g\u1eaft, t\u00f4i th\u01b0\u1eddng ph\u1ea3n h\u1ed3i nh\u01b0 th\u1ebf n\u00e0o?</p>\n    <div class=\"slabels\"><span>Ph\u00f2ng th\u1ee7 ngay</span><span>T\u00f2 m\u00f2 & h\u1ecfi th\u00eam</span></div>\n    <input type=\"range\" class=\"sslider\" min=\"1\" max=\"10\" value=\"5\" id=\"sl4\" oninput=\"SL4()\">\n    <div class=\"sval\" id=\"sv4\">5 / 10</div>\n    <div style=\"margin-top:17px\">\n      <label class=\"rlabel\">T\u00ecnh hu\u1ed1ng c\u1ea3m x\u00fac kh\u00f3 nh\u1ea5t g\u1ea7n \u0111\u00e2y trong c\u00f4ng vi\u1ec7c HR c\u1ee7a t\u00f4i:</label>\n      <textarea class=\"rinput\" id=\"r4\" placeholder=\"M\u00f4 t\u1ea3 ng\u1eafn \u2014 kh\u00f4ng c\u1ea7n ho\u00e0n h\u1ea3o, ch\u1ec9 c\u1ea7n th\u1eadt...\" oninput=\"CR4()\"></textarea>\n      <div class=\"chint\" id=\"rh4\">Nh\u1eadp \u00edt nh\u1ea5t 20 k\u00fd t\u1ef1 \u0111\u1ec3 ti\u1ebfp t\u1ee5c</div>\n    </div>\n  </div>\n\n  <div class=\"tw\">\n    <div class=\"tw-label\">C\u00e2u mang \u0111i \u00b7 B\u00e0i 4</div>\n    <div class=\"tw-text\">\"Gi\u1eefa k\u00edch th\u00edch v\u00e0 ph\u1ea3n \u1ee9ng lu\u00f4n c\u00f3 m\u1ed9t kho\u1ea3ng tr\u1ed1ng. Luy\u1ec7n t\u1eadp \u0111\u1ec3 m\u1edf r\u1ed9ng kho\u1ea3ng tr\u1ed1ng \u0111\u00f3 \u2014 \u0111\u00f3 l\u00e0 n\u01a1i EQ th\u1eadt s\u1ef1 s\u1ed1ng.\"</div>\n    <div class=\"tw-sig\">\u2014 TaHien \u00b7 CHCO Golden Gate Group</div>\n  </div>\n  <div class=\"navbtns\">\n    <button class=\"btnprev\" onclick=\"go(3)\">\u2190 Quay l\u1ea1i</button>\n    <button class=\"btnnext\" id=\"n4\" onclick=\"go(5)\" disabled>Ti\u1ebfp theo \u2192</button>\n  </div>\n  <div class=\"ulock\" id=\"h4\">Chia s\u1ebb \u0111\u1ec3 ti\u1ebfp t\u1ee5c (t\u1ed1i thi\u1ec3u 20 k\u00fd t\u1ef1)</div>\n</div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 M5 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div class=\"mv\" id=\"m5\">\n  <div class=\"hero\">\n    <div class=\"hero-bg\"><div class=\"hero-grad\"></div><div class=\"hero-pattern\"></div></div>\n    <div class=\"hero-overlay\"></div>\n    <div class=\"hero-content\">\n      <div class=\"hero-badge\">EQ & Self-Mastery \u00b7 C\u1ea5p 1</div>\n      <div class=\"hero-num\">B\u00e0i 5 / 6</div>\n      <div class=\"hero-title\">Resilience \u2014 ph\u1ee5c h\u1ed3i sau nh\u1eefng ng\u00e0y t\u1ec7 nh\u1ea5t</div>\n    </div>\n  </div>\n\n  <div class=\"lead\">\"Kh\u00f4ng c\u00f3 ngh\u1ec1 n\u00e0o trong t\u1ed5 ch\u1ee9c nh\u1eadn nhi\u1ec1u 'kh\u00f4ng' h\u01a1n HR. Kh\u00f4ng ng\u00e2n s\u00e1ch. Kh\u00f4ng \u0111\u01b0\u1ee3c ph\u00ea duy\u1ec7t. Kh\u00f4ng \u0111\u01b0\u1ee3c \u1ee7ng h\u1ed9. V\u00e0 \u0111\u00f4i khi \u2014 kh\u00f4ng \u0111\u01b0\u1ee3c c\u1ea3m \u01a1n d\u00f9 l\u00e0m \u0111\u00fang.\"</div>\n\n  <div class=\"ins\">\n    <div class=\"ins-label\">D\u1eef li\u1ec7u \u00b7 SHRM Research 2024</div>\n    <p><b style=\"color:var(--gold)\">42%</b> HR professionals b\u00e1o c\u00e1o m\u1ee9c \u0111\u1ed9 burnout cao \u2014 cao h\u01a1n b\u00ecnh qu\u00e2n l\u1ef1c l\u01b0\u1ee3ng lao \u0111\u1ed9ng <b style=\"color:var(--gold)\">18 \u0111i\u1ec3m ph\u1ea7n tr\u0103m.</b> HR l\u00e0 ngh\u1ec1 dual stress: x\u1eed l\u00fd stress b\u1ea3n th\u00e2n l\u1eabn h\u1ea5p thu stress c\u1ee7a ng\u01b0\u1eddi kh\u00e1c m\u1ed7i ng\u00e0y.</p>\n  </div>\n\n  <div class=\"sec-title\">4 tr\u1ee5 c\u1ed9t resilience cho ng\u01b0\u1eddi l\u00e0m HR</div>\n  <div class=\"grid2\">\n    <div class=\"card\"><div class=\"cn\">Tr\u1ee5 c\u1ed9t 1</div><div class=\"ct\">Ranh gi\u1edbi c\u1ea3m x\u00fac r\u00f5 r\u00e0ng</div><div class=\"cd\">Khi nh\u00e2n vi\u00ean kh\u00f4ng h\u1ea1nh ph\u00fac \u2014 \u0111\u00f3 kh\u00f4ng ph\u1ea3i l\u00e0 th\u1ea5t b\u1ea1i c\u00e1 nh\u00e2n c\u1ee7a HR. HR t\u1ea1o \u0111i\u1ec1u ki\u1ec7n, kh\u00f4ng ki\u1ec3m so\u00e1t c\u1ea3m x\u00fac ng\u01b0\u1eddi kh\u00e1c.</div></div>\n    <div class=\"card\"><div class=\"cn\">Tr\u1ee5 c\u1ed9t 2</div><div class=\"ct\">H\u1ec7 th\u1ed1ng n\u1ea1p l\u1ea1i c\u00f3 \u00fd th\u1ee9c</div><div class=\"cd\">Kh\u00f4ng ph\u1ea3i \"ngh\u1ec9 khi c\u00f3 th\u1ec3\" \u2014 m\u00e0 l\u00e0 l\u1ecbch c\u1ed1 \u0111\u1ecbnh. Sau ng\u00e0y n\u1eb7ng c\u1ea3m x\u00fac, c\u01a1 th\u1ec3 c\u1ea7n th\u1eddi gian kh\u00f4ng x\u1eed l\u00fd th\u00f4ng tin x\u00e3 h\u1ed9i.</div></div>\n    <div class=\"card\"><div class=\"cn\">Tr\u1ee5 c\u1ed9t 3</div><div class=\"ct\">Anchor story</div><div class=\"cd\">M\u1ed9t c\u00e2u chuy\u1ec7n c\u1ee5 th\u1ec3 v\u1ec1 l\u1ea7n b\u1ea1n t\u1ea1o ra s\u1ef1 kh\u00e1c bi\u1ec7t th\u1eadt s\u1ef1 cho m\u1ed9t ng\u01b0\u1eddi. K\u00e9o ra khi c\u1ea7n \u2014 \u0111\u1eb7c bi\u1ec7t trong nh\u1eefng ng\u00e0y t\u1ec7 nh\u1ea5t.</div></div>\n    <div class=\"card\"><div class=\"cn\">Tr\u1ee5 c\u1ed9t 4</div><div class=\"ct\">K\u1ebft n\u1ed1i c\u1ed9ng \u0111\u1ed3ng HR</div><div class=\"cd\">Kh\u00f4ng ai hi\u1ec3u \u00e1p l\u1ef1c c\u1ee7a ngh\u1ec1 HR b\u1eb1ng ng\u01b0\u1eddi c\u0169ng l\u00e0m HR. S\u1ef1 c\u00f4 l\u1eadp l\u00e0 k\u1ebb th\u00f9 l\u1edbn nh\u1ea5t c\u1ee7a resilience.</div></div>\n  </div>\n\n  <div class=\"ex\">\n    <div class=\"ex-head\">\n      <div class=\"ex-ico\">\u26a1</div>\n      <div><div class=\"ex-label\">Cam k\u1ebft c\u00e1 nh\u00e2n</div><div class=\"ex-sub\">Ch\u1ecdn \u00edt nh\u1ea5t 2 \u0111\u1ec3 ti\u1ebfp t\u1ee5c</div></div>\n    </div>\n    <p style=\"font-size:12.5px;color:var(--muted);margin-bottom:13px\">T\u00f4i s\u1ebd th\u1ef1c h\u00e0nh nh\u1eefng \u0111i\u1ec1u n\u00e0y trong tu\u1ea7n t\u1edbi:</p>\n    <div id=\"cl5\">\n      <div class=\"chi\" onclick=\"TC(this,'5')\" data-on=\"false\"><div class=\"chbox\"></div><div class=\"chtext\">Sau m\u1ed7i cu\u1ed9c tr\u00f2 chuy\u1ec7n c\u1ea3m x\u00fac n\u1eb7ng, d\u00e0nh 5 ph\u00fat kh\u00f4ng nh\u00ecn \u0111i\u1ec7n tho\u1ea1i<small>\u0110\u1ec3 cortisol h\u1ea1 xu\u1ed1ng tr\u01b0\u1edbc khi x\u1eed l\u00fd task ti\u1ebfp theo</small></div></div>\n      <div class=\"chi\" onclick=\"TC(this,'5')\" data-on=\"false\"><div class=\"chbox\"></div><div class=\"chtext\">Vi\u1ebft \"anchor story\" \u2014 m\u1ed9t kho\u1ea3nh kh\u1eafc HR t\u00f4i t\u1ea1o ra s\u1ef1 kh\u00e1c bi\u1ec7t th\u1eadt s\u1ef1<small>L\u01b0u \u1edf n\u01a1i d\u1ec5 t\u00ecm \u0111\u1ec3 k\u00e9o ra khi ng\u00e0y t\u1ec7</small></div></div>\n      <div class=\"chi\" onclick=\"TC(this,'5')\" data-on=\"false\"><div class=\"chbox\"></div><div class=\"chtext\">X\u00e1c \u0111\u1ecbnh ranh gi\u1edbi: c\u00f4ng vi\u1ec7c n\u00e0o l\u00e0 tr\u00e1ch nhi\u1ec7m c\u1ee7a t\u00f4i \u2014 v\u00e0 c\u00f4ng vi\u1ec7c n\u00e0o kh\u00f4ng?<small>Vi\u1ebft ra, kh\u00f4ng ch\u1ec9 ngh\u0129 trong \u0111\u1ea7u</small></div></div>\n      <div class=\"chi\" onclick=\"TC(this,'5')\" data-on=\"false\"><div class=\"chbox\"></div><div class=\"chtext\">K\u1ebft n\u1ed1i v\u1edbi \u00edt nh\u1ea5t 1 HR kh\u00e1c \u0111\u1ec3 chia s\u1ebb \u00e1p l\u1ef1c ngh\u1ec1 nghi\u1ec7p<small>Kh\u00f4ng ph\u1ea3i than v\u00e3n \u2014 \u0111\u1ec3 c\u1ea3m th\u1ea5y kh\u00f4ng \u0111\u01a1n \u0111\u1ed9c</small></div></div>\n    </div>\n    <div class=\"qfb\" id=\"cf5\"></div>\n  </div>\n\n  <div class=\"tw\">\n    <div class=\"tw-label\">C\u00e2u mang \u0111i \u00b7 B\u00e0i 5</div>\n    <div class=\"tw-text\">\"Resilience l\u00e0 c\u01a1 b\u1eafp \u2014 c\u1ea7n \u0111\u01b0\u1ee3c t\u1eadp luy\u1ec7n, c\u1ea7n \u0111\u01b0\u1ee3c ngh\u1ec9 ng\u01a1i, v\u00e0 c\u1ea7n \u0111\u01b0\u1ee3c nu\u00f4i d\u01b0\u1ee1ng. HR kh\u00f4ng th\u1ec3 ch\u0103m s\u00f3c ng\u01b0\u1eddi kh\u00e1c t\u1eeb m\u1ed9t chi\u1ebfc c\u1ed1c r\u1ed7ng.\"</div>\n    <div class=\"tw-sig\">\u2014 TaHien \u00b7 CHCO Golden Gate Group</div>\n  </div>\n  <div class=\"navbtns\">\n    <button class=\"btnprev\" onclick=\"go(4)\">\u2190 Quay l\u1ea1i</button>\n    <button class=\"btnnext\" id=\"n5\" onclick=\"go(6)\" disabled>Ti\u1ebfp theo \u2192</button>\n  </div>\n  <div class=\"ulock\" id=\"h5\">Ch\u1ecdn \u00edt nh\u1ea5t 2 cam k\u1ebft \u0111\u1ec3 ti\u1ebfp t\u1ee5c</div>\n</div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 M6 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div class=\"mv\" id=\"m6\">\n  <div class=\"hero\">\n    <div class=\"hero-bg\"><div class=\"hero-grad\"></div><div class=\"hero-pattern\"></div></div>\n    <div class=\"hero-overlay\"></div>\n    <div class=\"hero-content\">\n      <div class=\"hero-badge\">EQ & Self-Mastery \u00b7 B\u00e0i cu\u1ed1i</div>\n      <div class=\"hero-num\">B\u00e0i 6 / 6</div>\n      <div class=\"hero-title\">H\u1ec7 th\u1ed1ng EQ 5 ph\u00fat \u2014 \u00e1p d\u1ee5ng ngay ng\u00e0y mai</div>\n    </div>\n  </div>\n\n  <div class=\"lead\">\"Ki\u1ebfn th\u1ee9c v\u1ec1 EQ m\u00e0 kh\u00f4ng \u0111\u01b0\u1ee3c th\u1ef1c h\u00e0nh s\u1ebd bi\u1ebfn m\u1ea5t trong 72 gi\u1edd. B\u00e0i n\u00e0y l\u00e0 b\u1ed9 c\u00f4ng c\u1ee5 b\u1ea1n mang ra d\u00f9ng ngay t\u1eeb ng\u00e0y mai \u2014 kh\u00f4ng ph\u1ea3i l\u00fd thuy\u1ebft th\u00eam n\u1eefa.\"</div>\n\n  <div class=\"sec-title\">H\u1ec7 th\u1ed1ng EQ 5 ph\u00fat \u00b7 M\u1ed7i ng\u00e0y l\u00e0m vi\u1ec7c</div>\n  <div class=\"card\" style=\"margin-bottom:9px\">\n    <div class=\"cn\" style=\"color:var(--cyan)\">S\u00e1ng \u00b7 2 ph\u00fat</div>\n    <div class=\"ct\">Check-in c\u1ea3m x\u00fac b\u1ea3n th\u00e2n</div>\n    <div class=\"cd\">Tr\u01b0\u1edbc khi b\u1eaft \u0111\u1ea7u cu\u1ed9c tr\u00f2 chuy\u1ec7n \u0111\u1ea7u ti\u00ean: \"H\u00f4m nay t\u00f4i \u0111ang \u1edf tr\u1ea1ng th\u00e1i c\u1ea3m x\u00fac n\u00e0o? C\u00f3 th\u1ee9 g\u00ec \u0111ang chi\u1ebfm ch\u1ed7 trong \u0111\u1ea7u kh\u00f4ng?\" Kh\u00f4ng c\u1ea7n gi\u1ea3i quy\u1ebft \u2014 ch\u1ec9 c\u1ea7n nh\u1eadn ra.</div>\n  </div>\n  <div class=\"card\" style=\"margin-bottom:9px\">\n    <div class=\"cn\" style=\"color:var(--gold)\">Trong ng\u00e0y \u00b7 10 gi\u00e2y</div>\n    <div class=\"ct\">STOP technique tr\u01b0\u1edbc m\u1ed7i cu\u1ed9c tr\u00f2 chuy\u1ec7n quan tr\u1ecdng</div>\n    <div class=\"cd\"><b style=\"color:var(--text)\">S</b>top \u00b7 <b style=\"color:var(--text)\">T</b>ake a breath \u00b7 <b style=\"color:var(--text)\">O</b>bserve (t\u00f4i c\u1ea3m th\u1ea5y g\u00ec? ng\u01b0\u1eddi kia c\u1ea7n g\u00ec?) \u00b7 <b style=\"color:var(--text)\">P</b>roceed. 10 gi\u00e2y \u2014 nh\u01b0ng thay \u0111\u1ed5i ho\u00e0n to\u00e0n ch\u1ea5t l\u01b0\u1ee3ng cu\u1ed9c tr\u00f2 chuy\u1ec7n.</div>\n  </div>\n  <div class=\"card\" style=\"margin-bottom:18px\">\n    <div class=\"cn\" style=\"color:#a78bfa\">Cu\u1ed1i ng\u00e0y \u00b7 3 ph\u00fat</div>\n    <div class=\"ct\">Emotional debrief</div>\n    <div class=\"cd\">Cu\u1ed9c tr\u00f2 chuy\u1ec7n n\u00e0o h\u00f4m nay \u1ea3nh h\u01b0\u1edfng c\u1ea3m x\u00fac m\u00ecnh nhi\u1ec1u nh\u1ea5t? Ph\u1ea3n \u1ee9ng c\u1ee7a m\u00ecnh c\u00f3 ph\u00f9 h\u1ee3p kh\u00f4ng? N\u1ebfu l\u00e0m l\u1ea1i, m\u00ecnh s\u1ebd l\u00e0m kh\u00e1c \u0111i\u1ec1u g\u00ec? \u2014 Kh\u00f4ng ph\u00e1n x\u00e9t, ch\u1ec9 quan s\u00e1t.</div>\n  </div>\n\n  <div class=\"hl\">\n    <div class=\"hl-label\">3 c\u00e2u h\u1ecfi lu\u00f4n an to\u00e0n trong t\u00ecnh hu\u1ed1ng c\u1ea3m x\u00fac kh\u00f3</div>\n    <p style=\"margin-bottom:7px\">\u2460 <b style=\"color:var(--cyan)\">\"\u0110i\u1ec1u g\u00ec quan tr\u1ecdng nh\u1ea5t v\u1edbi anh/ch\u1ecb trong t\u00ecnh hu\u1ed1ng n\u00e0y?\"</b> \u2014 d\u1ecbch chuy\u1ec3n t\u1eeb c\u1ea3m x\u00fac sang nhu c\u1ea7u</p>\n    <p style=\"margin-bottom:7px\">\u2461 <b style=\"color:var(--cyan)\">\"Anh/ch\u1ecb mu\u1ed1n t\u00f4i gi\u00fap theo c\u00e1ch n\u00e0o nh\u1ea5t?\"</b> \u2014 trao quy\u1ec1n ki\u1ec3m so\u00e1t cho ng\u01b0\u1eddi kia</p>\n    <p>\u2462 <b style=\"color:var(--cyan)\">\"C\u00f2n \u0111i\u1ec1u g\u00ec anh/ch\u1ecb ch\u01b0a n\u00f3i m\u00e0 mu\u1ed1n t\u00f4i bi\u1ebft kh\u00f4ng?\"</b> \u2014 t\u1ea1o kh\u00f4ng gian cho nh\u1eefng g\u00ec b\u1ecb gi\u1ea5u</p>\n  </div>\n\n  <div class=\"ex\">\n    <div class=\"ex-head\">\n      <div class=\"ex-ico\">\u270d\ufe0f</div>\n      <div><div class=\"ex-label\">Cam k\u1ebft cu\u1ed1i kh\u00f3a</div><div class=\"ex-sub\">\u0110i\u1ec1u \u0111\u1ea7u ti\u00ean t\u00f4i s\u1ebd \u00e1p d\u1ee5ng ngay ng\u00e0y mai</div></div>\n    </div>\n    <textarea class=\"rinput\" id=\"r6\" placeholder=\"vd: Tr\u01b0\u1edbc bu\u1ed5i calibration, t\u00f4i s\u1ebd d\u00e0nh 10 gi\u00e2y STOP \u0111\u1ec3 nh\u1eafc m\u00ecnh r\u1eb1ng m\u1ecdi ng\u01b0\u1eddi trong ph\u00f2ng \u0111\u1ec1u \u0111ang lo l\u1eafng \u2014 kh\u00f4ng ph\u1ea3i ch\u1ec9 m\u00ecnh t\u00f4i...\" oninput=\"CR6()\" style=\"min-height:96px\"></textarea>\n    <div class=\"chint\" id=\"rh6\">Nh\u1eadp \u00edt nh\u1ea5t 30 k\u00fd t\u1ef1 \u0111\u1ec3 ho\u00e0n th\u00e0nh kh\u00f3a h\u1ecdc</div>\n  </div>\n\n  <div class=\"tw\">\n    <div class=\"tw-label\">C\u00e2u mang \u0111i \u00b7 To\u00e0n kh\u00f3a</div>\n    <div class=\"tw-text\">\"EQ kh\u00f4ng ph\u1ea3i th\u1ee9 b\u1ea1n c\u00f3 hay kh\u00f4ng c\u00f3. \u0110\u00f3 l\u00e0 th\u1ee9 b\u1ea1n x\u00e2y d\u1ef1ng m\u1ed7i ng\u00e0y \u2014 trong t\u1eebng cu\u1ed9c tr\u00f2 chuy\u1ec7n, t\u1eebng kho\u1ea3nh kh\u1eafc d\u1eebng l\u1ea1i, t\u1eebng l\u1ea7n ch\u1ecdn t\u00f2 m\u00f2 thay v\u00ec ph\u00e1n x\u00e9t.\"</div>\n    <div class=\"tw-sig\">\u2014 TaHien \u00b7 CHCO Golden Gate Group \u00b7 PeopleOS Community 2026</div>\n  </div>\n  <div class=\"navbtns\">\n    <button class=\"btnprev\" onclick=\"go(5)\">\u2190 Quay l\u1ea1i</button>\n    <button class=\"btnnext\" id=\"n6\" onclick=\"done()\" disabled>Ho\u00e0n th\u00e0nh kh\u00f3a h\u1ecdc \u2713</button>\n  </div>\n  <div class=\"ulock\" id=\"h6\">Nh\u1eadp cam k\u1ebft \u0111\u1ec3 ho\u00e0n th\u00e0nh (t\u1ed1i thi\u1ec3u 30 k\u00fd t\u1ef1)</div>\n</div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 COMPLETE \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div class=\"cscreen\" id=\"complete\">\n  <div class=\"cico\">\ud83c\udfc6</div>\n  <div class=\"ctitle\">Ho\u00e0n th\u00e0nh xu\u1ea5t s\u1eafc!</div>\n  <div class=\"csub\">B\u1ea1n \u0111\u00e3 ho\u00e0n th\u00e0nh kh\u00f3a <b>EQ & Self-Mastery</b>.<br>6 b\u00e0i h\u1ecdc \u00b7 108 XP \u0111\u00e3 \u0111\u01b0\u1ee3c ghi nh\u1eadn.</div>\n  <div class=\"certcard\">\n    <div class=\"cert-lbl\">Ch\u1ee9ng ch\u1ec9 ho\u00e0n th\u00e0nh \u00b7 PeopleOS</div>\n    <div class=\"cert-name\">EQ & Self-Mastery</div>\n    <div class=\"cert-course\">C\u1ea5p 1 \u2014 HR Staff & Specialist \u00b7 6 modules \u00b7 ~18 ph\u00fat</div>\n    <div class=\"cert-sig\">TaHien \u2014 CHCO Golden Gate Group \u2014 bi\u00ean so\u1ea1n cho c\u1ed9ng \u0111\u1ed3ng HR Vietnam.<br>PeopleOS Community \u00b7 2026</div>\n  </div>\n  <button class=\"btncert\" onclick=\"alert('T\u00ednh n\u0103ng xu\u1ea5t PDF s\u1ebd c\u00f3 trong phi\u00ean b\u1ea3n \u0111\u1ea7y \u0111\u1ee7!')\">T\u1ea3i ch\u1ee9ng ch\u1ec9 PDF</button>\n  <button class=\"btnnext2\" onclick=\"window.location.href='/'\">\u2190 V\u1ec1 Learning Hub</button>\n</div>\n\n</div><!-- /app -->\n\n<script>\nvar cur=1,tot=6,doneM={};\n\n/* \u2500\u2500 BUILD UI \u2500\u2500 */\nfunction buildDots(){\n  var c=document.getElementById('dots');c.innerHTML='';\n  for(var i=1;i<=tot;i++){\n    var d=document.createElement('div');\n    d.className='dot'+(i===cur?' active':(doneM[i]?' done':''));\n    (function(n){d.onclick=function(){if(n<=cur||doneM[n-1])go(n)}})(i);\n    c.appendChild(d);\n  }\n}\nfunction updProg(){\n  var p=Math.round(((cur-1)/tot)*100);\n  document.getElementById('pfill').style.width=p+'%';\n  document.getElementById('ppct').textContent=p+'%';\n  document.getElementById('plabel').textContent='B\u00e0i '+cur+' / '+tot;\n}\nfunction go(n){\n  document.getElementById('m'+cur).classList.remove('active');\n  doneM[cur]=true;cur=n;\n  var el=document.getElementById('m'+cur);\n  if(el)el.classList.add('active');\n  buildDots();updProg();\n  window.scrollTo({top:0,behavior:'smooth'});\n}\nfunction unlock(nb,nh){\n  var b=document.getElementById(nb);if(b)b.disabled=false;\n  var h=document.getElementById(nh);if(h)h.style.display='none';\n}\n\n/* \u2500\u2500 M1 QUIZ \u2500\u2500 */\nfunction A1(el,ans){\n  document.querySelectorAll('#q1opts .qopt').forEach(function(o){o.disabled=true});\n  var fb=document.getElementById('qf1');\n  if(ans==='B'){\n    el.classList.add('correct');\n    fb.className='qfb show correct';\n    fb.textContent='\u0110\u00fang! C\u00e2u h\u1ecfi m\u1edf gi\u00fap hi\u1ec3u lo ng\u1ea1i th\u1eadt s\u1ef1 c\u1ee7a manager tr\u01b0\u1edbc khi gi\u1ea3i th\u00edch. EQ cao l\u00e0 t\u00f2 m\u00f2 tr\u01b0\u1edbc, gi\u1ea3i th\u00edch sau.';\n    unlock('n1','h1');\n  } else {\n    el.classList.add('wrong');\n    document.querySelectorAll('#q1opts .qopt')[1].classList.add('correct');\n    fb.className='qfb show wrong';\n    fb.textContent='Ch\u01b0a \u0111\u00fang. Gi\u1ea3i th\u00edch ngay (A) t\u1ea1o tranh lu\u1eadn. \u0110\u1ed3ng \u00fd (C) m\u1ea5t uy t\u00edn. B\u00e1o c\u00e1o (D) n\u00e9 tr\u00e1nh v\u1ea5n \u0111\u1ec1. EQ cao l\u00e0 h\u1ecfi tr\u01b0\u1edbc \u2014 t\u00ecm hi\u1ec3u nhu c\u1ea7u th\u1eadt s\u1ef1 c\u1ee7a ng\u01b0\u1eddi kia.';\n    setTimeout(function(){unlock('n1','h1')},1500);\n  }\n}\n\n/* \u2500\u2500 M2 EMOTION \u2500\u2500 */\nfunction PE(el,type){\n  document.querySelectorAll('#emg .embtn').forEach(function(b){b.disabled=true});\n  var fb=document.getElementById('ef2');\n  el.classList.add('sel');\n  if(type==='ok'){\n    fb.className='qfb show correct';\n    fb.textContent='Ch\u00ednh x\u00e1c! Anh \u1ea5y \u0111ang tr\u1ea3i qua n\u1ed7i bu\u1ed3n / c\u1ea3m gi\u00e1c v\u00f4 h\u00ecnh \u2014 kh\u00f4ng \u0111\u01b0\u1ee3c nh\u00ecn nh\u1eadn sau n\u0103m th\u00e1ng c\u1ed1ng hi\u1ebfn. Im l\u1eb7ng + r\u00fat lui l\u00e0 d\u1ea5u hi\u1ec7u \u0111i\u1ec3n h\u00ecnh. HR c\u1ea7n ch\u1ee7 \u0111\u1ed9ng 1:1 trong v\u00f2ng 48 gi\u1edd.';\n    unlock('n2','h2');\n  } else {\n    document.querySelectorAll('#emg .embtn')[1].classList.add('sel');\n    fb.className='qfb show wrong';\n    fb.textContent='G\u1ea7n \u0111\u00fang nh\u01b0ng ch\u01b0a tr\u00fang. Ng\u01b0\u1eddi im l\u1eb7ng v\u00e0 r\u00fat lui th\u01b0\u1eddng \u0111ang bu\u1ed3n / c\u1ea3m th\u1ea5y v\u00f4 h\u00ecnh \u2014 kh\u00f4ng ph\u1ea3i t\u1ee9c gi\u1eadn (b\u00f9ng ph\u00e1t) hay s\u1ee3 (n\u00f3i nhi\u1ec1u h\u01a1n).';\n    setTimeout(function(){unlock('n2','h2')},1500);\n  }\n}\n\n/* \u2500\u2500 M3 QUIZ \u2500\u2500 */\nfunction A3(el,ans){\n  document.querySelectorAll('#q3opts .qopt').forEach(function(o){o.disabled=true});\n  var fb=document.getElementById('qf3');\n  if(ans==='C'){\n    el.classList.add('correct');\n    fb.className='qfb show correct';\n    fb.textContent='Ho\u00e0n h\u1ea3o! T\u1ea1m d\u1eebng mua th\u1eddi gian, c\u00e2u h\u1ecfi m\u1edf t\u1ea1o kh\u00f4ng gian an to\u00e0n. Kh\u00f4ng h\u1ecfi th\u1eb3ng (g\u00e2y ph\u00f2ng th\u1ee7), kh\u00f4ng b\u1ecf qua (m\u1ea5t th\u00f4ng tin quan tr\u1ecdng), kh\u00f4ng k\u1ebft th\u00fac s\u1edbm (\u0111\u00f3ng c\u1eeda).';\n    unlock('n3','h3');\n  } else {\n    el.classList.add('wrong');\n    document.querySelectorAll('#q3opts .qopt')[2].classList.add('correct');\n    fb.className='qfb show wrong';\n    fb.textContent='Ch\u01b0a \u0111\u00fang. \u0110\u00e1p \u00e1n C t\u1ea1o kh\u00f4ng gian an to\u00e0n nh\u1ea5t. H\u1ecfi th\u1eb3ng (A) g\u00e2y ph\u00f2ng th\u1ee7, b\u1ecf qua (B) m\u1ea5t th\u00f4ng tin quan tr\u1ecdng, k\u1ebft th\u00fac s\u1edbm (D) \u0111\u00f3ng c\u01a1 h\u1ed9i.';\n    setTimeout(function(){unlock('n3','h3')},1500);\n  }\n}\n\n/* \u2500\u2500 M4 SLIDER + REFLECT \u2500\u2500 */\nvar sl4moved=false;\nfunction SL4(){\n  var v=document.getElementById('sl4').value;\n  document.getElementById('sv4').textContent=v+' / 10';\n  sl4moved=true;\n}\nfunction CR4(){\n  var t=document.getElementById('r4').value;\n  var h=document.getElementById('rh4');\n  var left=Math.max(0,20-t.length);\n  if(t.length>=20){\n    h.textContent='C\u1ea3m \u01a1n b\u1ea1n \u0111\u00e3 chia s\u1ebb th\u1eadt l\u00f2ng \u2713';h.style.color='var(--cyan)';\n    unlock('n4','h4');\n  } else {\n    h.textContent='C\u00f2n '+left+' k\u00fd t\u1ef1 n\u1eefa';h.style.color='var(--subtle)';\n  }\n}\n\n/* \u2500\u2500 M5 CHECKLIST \u2500\u2500 */\nvar cc5=0;\nfunction TC(el,mid){\n  var box=el.querySelector('.chbox');\n  var on=el.getAttribute('data-on')==='true';\n  if(!on){box.classList.add('on');el.setAttribute('data-on','true');cc5++}\n  else{box.classList.remove('on');el.setAttribute('data-on','false');cc5--}\n  var fb=document.getElementById('cf5');\n  if(cc5>=2){\n    fb.className='qfb show correct';\n    fb.textContent='T\u1ed1t l\u1eafm! B\u1ea1n \u0111\u00e3 cam k\u1ebft '+cc5+' h\u00e0nh \u0111\u1ed9ng. Ghi v\u00e0o l\u1ecbch \u0111\u1ec3 kh\u00f4ng qu\u00ean.';\n    unlock('n5','h5');\n  } else {\n    fb.className='';\n    var nb=document.getElementById('n5');if(nb)nb.disabled=true;\n    var hb=document.getElementById('h5');if(hb)hb.style.display='';\n  }\n}\n\n/* \u2500\u2500 M6 FINAL REFLECT \u2500\u2500 */\nfunction CR6(){\n  var t=document.getElementById('r6').value;\n  var h=document.getElementById('rh6');\n  var left=Math.max(0,30-t.length);\n  if(t.length>=30){\n    h.textContent='Cam k\u1ebft \u0111\u00e3 \u0111\u01b0\u1ee3c ghi nh\u1eadn \u2713';h.style.color='var(--cyan)';\n    unlock('n6','h6');\n  } else {\n    h.textContent='C\u00f2n '+left+' k\u00fd t\u1ef1 n\u1eefa';h.style.color='var(--subtle)';\n  }\n}\n\n/* \u2500\u2500 COMPLETE \u2500\u2500 */\nfunction done(){\n  document.getElementById('m6').style.display='none';\n  var cs=document.getElementById('complete');cs.classList.add('show');\n  doneM[6]=true;cur=7;\n  document.getElementById('pfill').style.width='100%';\n  document.getElementById('ppct').textContent='100%';\n  document.getElementById('plabel').textContent='Ho\u00e0n th\u00e0nh!';\n  buildDots();\n  window.scrollTo({top:0,behavior:'smooth'});\n  localStorage.setItem('peopleos_k1_done','true');\n}\n\n/* \u2500\u2500 INIT \u2500\u2500 */\nbuildDots();updProg();\n</script>\n</body>\n</html>\n";
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.write(html);
  res.end();
  return { props: {} };
}
